import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type InstagramViewCounterProps = Record<string, any>;

const InstagramViewCounter: React.FC<InstagramViewCounterProps> = ({
  targetCount = 15420,
  durationInSeconds = 3,
  textColor = "#ffffff",
  iconColor = "#ffffff",
  backgroundColor = "#000000",
  transparentBackground = true,
  pillOpacity = 0.5,
  fontSize = 60,
  labelText = "",
  showIcon = true,
}) => {
  
  {/* Load Google Fonts - Inter is standard for UI */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors for background
  const canvasBg = transparentBackground ? "transparent" : backgroundColor;
  
  // Calculate frames
  const durationInFrames = durationInSeconds * fps;
  
  // Counting Animation (Ease Out Expo for fast start, slow end)
  const currentCountRaw = interpolate(
    frame,
    [0, durationInFrames],
    [0, targetCount],
    {
      easing: Easing.out(Easing.exp),
      extrapolateRight: "clamp",
    }
  );

  const currentCount = Math.round(currentCountRaw);
  
  // Format number with commas (e.g., 15,420)
  const formattedCount = new Intl.NumberFormat('en-US').format(currentCount);

  // Dynamic Styles
  const pillStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: fontSize * 0.3,
    padding: `${fontSize * 0.2}px ${fontSize * 0.6}px`,
    borderRadius: fontSize * 2, // Pill shape
    backgroundColor: `${backgroundColor}${Math.floor(pillOpacity * 255).toString(16).padStart(2, '0')}`,
    fontFamily: "Inter, sans-serif",
    backdropFilter: "blur(4px)", // Typical Glassmorphism
    boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
  };

  const textStyle: React.CSSProperties = {
    color: textColor,
    fontSize: fontSize,
    fontWeight: 600,
    lineHeight: 1,
    fontVariantNumeric: "tabular-nums", // Keeps numbers from jittering width
    whiteSpace: "nowrap",
  };

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: canvasBg, 
        justifyContent: "center", 
        alignItems: "center" 
      }}
    >
      <div style={pillStyle}>
        {/* Play Icon (SVG) */}
        {showIcon && (
          <svg
            width={fontSize * 0.8}
            height={fontSize * 0.8}
            viewBox="0 0 24 24"
            fill={iconColor}
            xmlns="http://www.w3.org/2000/svg"
            style={{ minWidth: fontSize * 0.8 }}
          >
            <path d="M8 5V19L19 12L8 5Z" />
          </svg>
        )}

        {/* Counter Text */}
        <span style={textStyle}>
          {formattedCount}
        </span>
        
        {/* Optional Label (e.g. "views") */}
        {labelText && (
          <span style={{ ...textStyle, fontWeight: 400, opacity: 0.9 }}>
            {labelText}
          </span>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default InstagramViewCounter;